import React,{useEffect,useMemo,useState} from 'react';
import {ArrowDownLeft,ArrowUpRight,ArrowRightLeft,BarChart3,Wallet,BookOpen,ShieldCheck,LogOut,Menu,Bell,Mic,Download,Upload,CheckCircle2,AlertTriangle,Plus,Eye,Trash2,Send,FileText,Users,Landmark,Package,MessageCircle,Settings,Clock3,ChevronRight,Camera,Lock,BriefcaseBusiness,Search,Home,CalendarDays,ClipboardList,LayoutDashboard,PanelLeftClose,PanelLeftOpen,X,LifeBuoy,Tag,UserRound,ClipboardCheck} from 'lucide-react';
